#include "expression_reduction_internal.hpp"
#include "atomic_export.hpp"
#include <charconv>

namespace qpx {
namespace {
std::string number(double x){char b[64];const auto r=std::to_chars(b,b+sizeof(b),x,std::chars_format::general,17);if(r.ec!=std::errc{})throw std::runtime_error("Reduction numeric conversion failed");return {b,r.ptr};}
std::string tick(double x){char b[64];const auto r=std::to_chars(b,b+sizeof(b),x,std::chars_format::general,6);if(r.ec!=std::errc{})throw std::runtime_error("Reduction tick conversion failed");return {b,r.ptr};}
std::string csv(const std::string& s){std::string out="\"";for(auto c:s){out+=c;if(c=='"')out+='"';}return out+'"';}
std::string xml(const std::string& s){std::string out;for(auto c:s){if(static_cast<unsigned char>(c)<32 && c!='\t' && c!='\n' && c!='\r')throw std::invalid_argument("Reduction identifier contains an XML-incompatible control character");switch(c){case '&':out+="&amp;";break;case '<':out+="&lt;";break;case '>':out+="&gt;";break;case '"':out+="&quot;";break;case '\'':out+="&apos;";break;default:out+=c;}}return out;}
void limit(std::size_t n){if(!n || n>1024ull*1024*1024)throw std::invalid_argument("Reduction export limit must be1 byte..1GiB");}
void line(detail::AtomicExportFile& file,const std::string& s){file.write(s.data(),s.size());}
}
std::size_t save_expression_embedding_csv(const ExpressionReductionResult& r,const std::string& path,std::size_t bytes,const std::atomic<bool>* cancelled){limit(bytes);workflow_checkpoint(cancelled);detail::AtomicExportFile out(path,bytes,cancelled);const auto k=r.options().components;std::string header="result_id,source_sha256,value_source_sha256,value_domain,method,observation_index,observation_id,cluster";for(std::uint32_t c=0;c<k;++c)header+=",component_"+std::to_string(c+1);line(out,header+"\n");for(std::size_t i=0;i<r.observation_ids().size();++i){workflow_checkpoint(cancelled);std::string row=r.id()+","+r.source_sha256()+","+r.value_source_sha256()+","+csv(r.value_domain())+","+(r.options().center?"centered-pca":"uncentered-svd")+","+std::to_string(i)+","+csv(r.observation_ids()[i])+","+std::to_string(r.labels()[i]);for(std::uint32_t c=0;c<k;++c)row+=","+number(r.embedding()[i*k+c]);line(out,row+"\n");}workflow_checkpoint(cancelled);out.commit(false);return out.bytes();}
std::size_t save_expression_loadings_csv(const ExpressionReductionResult& r,const std::string& path,std::size_t bytes,const std::atomic<bool>* cancelled){limit(bytes);workflow_checkpoint(cancelled);detail::AtomicExportFile out(path,bytes,cancelled);const auto k=r.options().components;std::string header="result_id,source_sha256,feature_index,feature_id,mean";for(std::uint32_t c=0;c<k;++c)header+=",loading_"+std::to_string(c+1);line(out,header+"\n");for(std::size_t i=0;i<r.features().size();++i){workflow_checkpoint(cancelled);std::string row=r.id()+","+r.source_sha256()+","+std::to_string(r.features()[i])+","+csv(r.feature_ids()[i])+","+number(r.means()[i]);for(std::uint32_t c=0;c<k;++c)row+=","+number(r.loadings()[i*k+c]);line(out,row+"\n");}workflow_checkpoint(cancelled);out.commit(false);return out.bytes();}
std::size_t save_expression_reduction_svg(const ExpressionReductionResult& r,const std::string& path,std::size_t bytes,const std::atomic<bool>* cancelled){
    limit(bytes);workflow_checkpoint(cancelled);detail::AtomicExportFile out(path,bytes,cancelled);const auto n=r.observation_ids().size(),k=std::size_t(r.options().components);double xmin=INFINITY,xmax=-INFINITY,ymin=INFINITY,ymax=-INFINITY;
    for(std::size_t i=0;i<n;++i){const auto x=r.embedding()[i*k],y=k>1?r.embedding()[i*k+1]:0.;xmin=std::min(xmin,x);xmax=std::max(xmax,x);ymin=std::min(ymin,y);ymax=std::max(ymax,y);}if(xmin==xmax){xmin-=1;xmax+=1;}if(ymin==ymax){ymin-=1;ymax+=1;}const auto xrange=xmax-xmin,yrange=ymax-ymin;if(!std::isfinite(xrange) || !std::isfinite(yrange) || xrange<=0 || yrange<=0)throw std::invalid_argument("Reduction scatter limits are not representable");const auto px=[&](double x){return 160+680*((x-xmin)/xrange);};const auto py=[&](double y){return 730-620*((y-ymin)/yrange);};
    const std::array<const char*,32> colors{"#0072B2","#D55E00","#009E73","#CC79A7","#E69F00","#56B4E9","#7A5195","#4D4D4D","#003F5C","#58508D","#BC5090","#FF6361","#FFA600","#006D77","#83C5BE","#E29578","#5F0F40","#9A031E","#FB8B24","#E36414","#0F4C5C","#3A0CA3","#4361EE","#4CC9F0","#1B4332","#40916C","#74C69D","#A7C957","#6A4C93","#8AC926","#FFCA3A","#1982C4"};const auto method=r.options().center?"Centered PCA":"Uncentered SVD",axis=r.options().center?"PC":"SVD";
    line(out,"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1100\" height=\"850\" viewBox=\"0 0 1100 850\"><title>Native expression reduction</title><desc>Result "+r.id()+"; "+xml(r.value_domain())+"; centres and cluster labels are exploratory, not biological identities.</desc><rect width=\"1100\" height=\"850\" fill=\"white\"/><g font-family=\"sans-serif\" fill=\"#18212b\"><text x=\"80\" y=\"34\" font-size=\"23\">"+method+" / seeded k-means</text><text x=\"80\" y=\"60\" font-size=\"14\">"+std::to_string(n)+" observations; "+std::to_string(r.features().size())+" features; "+std::to_string(r.options().clusters)+" clusters; seed "+std::to_string(r.options().seed)+"; "+xml(r.value_domain())+"</text><path d=\"M160 100V730H850\" fill=\"none\" stroke=\"#536373\"/><text x=\"160\" y=\"755\" font-size=\"12\">"+tick(xmin)+"</text><text x=\"840\" y=\"755\" font-size=\"12\" text-anchor=\"end\">"+tick(xmax)+"</text><text x=\"150\" y=\"115\" font-size=\"12\" text-anchor=\"end\">"+tick(ymax)+"</text><text x=\"150\" y=\"730\" font-size=\"12\" text-anchor=\"end\">"+tick(ymin)+"</text><text x=\"450\" y=\"790\" text-anchor=\"middle\" font-size=\"15\">"+axis+"1 (energy fraction "+tick(r.component_energy()[0]/r.total_energy())+")</text><text x=\"30\" y=\"430\" transform=\"rotate(-90 30 430)\" text-anchor=\"middle\" font-size=\"15\">"+(k>1?std::string(axis)+"2 (energy fraction "+tick(r.component_energy()[1]/r.total_energy())+")":"One-component fit; vertical coordinate is zero")+"</text>");
    for(std::size_t i=0;i<n;++i){workflow_checkpoint(cancelled);const auto x=r.embedding()[i*k],y=k>1?r.embedding()[i*k+1]:0.;line(out,"<circle data-index=\""+std::to_string(i)+"\" data-cluster=\""+std::to_string(r.labels()[i])+"\" cx=\""+number(px(x))+"\" cy=\""+number(py(y))+"\" r=\"3\" fill=\""+colors[r.labels()[i]%colors.size()]+"\" fill-opacity=\"0.65\"><title>"+xml(r.observation_ids()[i])+"; cluster "+std::to_string(r.labels()[i])+"; "+axis+"1="+number(x)+(k>1?std::string("; ")+axis+"2="+number(y):"")+"</title></circle>");}
    for(std::uint32_t c=0;c<r.options().clusters;++c)line(out,"<rect x=\"910\" y=\""+std::to_string(110+c*19)+"\" width=\"10\" height=\"10\" fill=\""+colors[c%colors.size()]+"\"/><text x=\"930\" y=\""+std::to_string(120+c*19)+"\" font-size=\"13\">Cluster "+std::to_string(c)+"</text>");line(out,"<text x=\"80\" y=\"820\" font-size=\"12\">Exploratory clustering; "+std::string(r.converged()?"converged":"iteration limit reached")+"; result "+r.id()+"</text></g></svg>\n");workflow_checkpoint(cancelled);out.commit(false);return out.bytes();
}
}
